// A run's AI steps asked and written (docs/specs/026-plan/automations.md "AI actions"; blueprint automations.md
// "Phase 3: AI actions"). After the run's card writes, each AI step is one call to Workers AI through the api's `AI`
// binding (no key, no secret), its answer constrained by @liveplanner/items' aiOutcome and written by Automation:
// a comment marked Generated by AI, or one patch with history tag 'automation_ai'. A plan asks at most
// AUTOMATION_AI_PER_DAY a day, counted from the Audit Trail's lines (each call's carries `ai`), read once per wake.
// No binding, a model that errs or takes past 15 s, a reply that doesn't parse: the step fails with its reason.
// Test on a Card asks nothing and says what it would do. Never throws.
import {
  AI_CAPPED,
  AI_FAILED,
  AI_NOT_SET_UP,
  AI_SLOW,
  AI_UNREADABLE,
  AUTOMATION_AI_PER_DAY,
  aiCardInput,
  aiDryLine,
  aiOutcome,
  aiRequest,
  planLabels,
  readAiReply,
  type AiOutcome,
  type AiRequest,
  type AutomationAiTask,
  type AutomationRule,
  type AutomationStepLine,
  type Item,
  type PlannedAi,
} from '@liveplanner/items';
import { linksOfItem, readThreads } from '../../db/card-threads';
import { listItems, readItem } from '../../db/items';
import { reportServerEvent } from '../../server-telemetry';
import type { AutomationsAi, PlanEnv } from '../../types';
import type { AutomationPlan } from './automation-plan';
import type { HistorySource } from './automation-queue';
import type { Sql } from './automation-store';
import { addComment, patchCard, type WriteDeps } from './automation-writes';

export type { AutomationsAi } from '../../types';

// The model (Workers AI's catalogue, Nov 2026): a small, cheap instruct model with JSON mode, not on the deprecation
// list, its thinking mode turned off so an answer costs only its own tokens.
export const AUTOMATION_AI_MODEL = '@cf/google/gemma-4-26b-a4b-it';
export const AUTOMATION_AI_TIMEOUT_MS = 15_000;

const DAY_MS = 24 * 60 * 60 * 1000;

// The binding the room asks through, or null where there is none (tests, local dev without Cloudflare, a fork).
export function aiClient(env: Pick<PlanEnv, 'AI'>): AutomationsAi | null {
  return env.AI ?? null;
}

const midnight = (now: number) => Math.floor(now / DAY_MS) * DAY_MS;

// The AI calls the plan made today (UTC): the Audit Trail's lines marked `ai`, pending runs' too once settled, and
// Describe a Rule's asks.
export function aiToday(sql: Sql, now: number): number {
  const day = midnight(now);
  const row = sql
    .exec(
      `SELECT (SELECT COUNT(*) FROM automation_runs r, json_each(r.body, '$.steps') s
                WHERE r.at >= ? AND s.value ->> '$.ai' = 1)
            + (SELECT COUNT(*) FROM automation_ai_drafts WHERE at >= ?) AS n`,
      day,
      day,
    )
    .toArray()[0];
  return Number(row?.['n'] ?? 0);
}

// The rules Describe a Rule drafted today (UTC): each draft's first ask.
export function draftsToday(sql: Sql, now: number): number {
  const row = sql
    .exec(
      'SELECT COUNT(*) AS n FROM automation_ai_drafts WHERE at >= ? AND retry = 0',
      midnight(now),
    )
    .toArray()[0];
  return Number(row?.['n'] ?? 0);
}

// One Describe a Rule ask, counted; asks past two days go.
export function countDraftAsk(sql: Sql, now: number, retry: boolean): void {
  sql.exec('DELETE FROM automation_ai_drafts WHERE at < ?', midnight(now) - DAY_MS);
  sql.exec('INSERT INTO automation_ai_drafts (at, retry) VALUES (?, ?)', now, retry ? 1 : 0);
}

// Each call's telemetry, by task (literal types, so the telemetry catalogue's scan reads them).
function called(env: PlanEnv, task: AutomationAiTask): Promise<void> {
  switch (task) {
    case 'summarise':
      return reportServerEvent(env, 'Plan', 'Ran', 'AutomationAiSummarise');
    case 'card_type':
      return reportServerEvent(env, 'Plan', 'Ran', 'AutomationAiCardType');
    case 'triage':
      return reportServerEvent(env, 'Plan', 'Ran', 'AutomationAiTriage');
  }
}

export interface AiStepsInput {
  client: AutomationsAi | null;
  sql: Sql;
  // The wake's (or request's) count of today's calls, read once.
  state: { ai?: number };
  plan: AutomationPlan;
  rule: AutomationRule;
  card: Item;
  source: HistorySource;
  dry: boolean;
  gateway?: string;
}

export type AiStepsOutcome = {
  // The first step that failed, for the run's reason.
  failed?: string;
  // A step the day's cap skipped (the run is Skipped when nothing failed).
  skipped?: string;
};

const SLOW = Symbol('slow');

export type Asked = { ok: true; raw: unknown } | { ok: false; reason: string };

// One call, bounded by the timeout; the model's own error and a gateway's refusal are the same failure to a rule.
export async function ask(
  client: AutomationsAi,
  request: AiRequest,
  gateway: string | undefined,
): Promise<Asked> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const slow = new Promise<typeof SLOW>((resolve) => {
    timer = setTimeout(() => resolve(SLOW), AUTOMATION_AI_TIMEOUT_MS);
  });
  try {
    const raw = await Promise.race([
      client.run(
        AUTOMATION_AI_MODEL,
        { ...request, chat_template_kwargs: { enable_thinking: false } },
        gateway ? { gateway: { id: gateway } } : undefined,
      ),
      slow,
    ]);
    return raw === SLOW ? { ok: false, reason: AI_SLOW } : { ok: true, raw };
  } catch (error) {
    console.warn('[automations] ai.failed', { error: String(error) });
    return { ok: false, reason: AI_FAILED };
  } finally {
    clearTimeout(timer);
  }
}

// The newest comments on the card's threads this plan holds, text only.
async function latestComments(env: PlanEnv, planId: string, cardId: string): Promise<string[]> {
  const links = (await linksOfItem(env, planId, cardId)).filter((l) => l.home === planId);
  const threads = await readThreads(
    env,
    planId,
    links.map((l) => l.threadId),
  );
  return threads
    .flatMap((t) => t.comments)
    .sort((a, b) => b.createdAt - a.createdAt)
    .map((c) => c.text);
}

// The answer written: a comment, or the card's patch (none when it changes nothing), with what the line says.
async function write(
  deps: WriteDeps,
  input: AiStepsInput,
  card: Item,
  outcome: AiOutcome,
): Promise<{ ok: boolean; text: string; already?: true }> {
  if ('failed' in outcome) return { ok: false, text: outcome.failed };
  if ('comment' in outcome) {
    const wrote = await addComment(deps, input.rule, card, outcome.comment, { ai: true });
    return wrote.ok ? { ok: true, text: outcome.line } : { ok: false, text: wrote.reason };
  }
  if (outcome.already) return { ok: true, text: outcome.line, already: true };
  const wrote = await patchCard(
    deps,
    input.plan,
    input.rule,
    card.id,
    outcome.patch,
    input.source,
    'automation_ai',
  );
  return wrote.ok ? { ok: true, text: outcome.line } : { ok: false, text: wrote.reason };
}

// The run's AI steps: each line in `lines` (at `offset + p.line`) settled with what it did, the first failure and a
// capped step said back. Test on a Card (`dry`) asks nothing.
export async function runAiSteps(
  deps: WriteDeps,
  input: AiStepsInput,
  planned: readonly PlannedAi[],
  lines: AutomationStepLine[],
  offset: number,
): Promise<AiStepsOutcome> {
  if (planned.length === 0) return {};
  const out: AiStepsOutcome = {};
  const { plan } = input;
  const { env } = deps;
  const settle = (
    p: PlannedAi,
    ok: boolean,
    text: string,
    mark: { ai?: true; already?: true } = {},
  ) => {
    lines[offset + p.line] = { kind: 'action', ok, text, ...mark };
    if (!ok) out.failed ??= text;
  };
  let labels: string[] | null = null;
  const planLabelsNow = async () => (labels ??= planLabels(await listItems(deps.env, deps.planId)));
  for (const p of planned) {
    const task = p.ai.task;
    if (input.dry) {
      const choices = task === 'triage' ? await planLabelsNow() : [];
      settle(p, true, aiDryLine(p.ai, plan.outline, choices));
      continue;
    }
    if (!input.client) {
      settle(p, false, AI_NOT_SET_UP);
      continue;
    }
    input.state.ai ??= aiToday(input.sql, Date.now());
    if (input.state.ai >= AUTOMATION_AI_PER_DAY) {
      lines[offset + p.line] = { kind: 'action', ok: false, text: AI_CAPPED };
      out.skipped = AI_CAPPED;
      deps.defer(reportServerEvent(env, 'Plan', 'Ran', 'AutomationAiCapped'));
      continue;
    }
    const started = Date.now();
    const card = (await readItem(deps.env, deps.planId, input.card.id)) ?? input.card;
    const cardInput = aiCardInput(
      card,
      plan.outline,
      task === 'summarise' ? await latestComments(deps.env, deps.planId, card.id) : [],
    );
    const choices =
      task === 'card_type'
        ? { types: plan.outline.types.map((t) => t.label) }
        : task === 'triage'
          ? { labels: await planLabelsNow() }
          : {};
    // The call counts whatever it answers.
    input.state.ai += 1;
    deps.defer(called(deps.env, task));
    const asked = await ask(input.client, aiRequest(task, cardInput, choices), input.gateway);
    const reply = asked.ok ? readAiReply(asked.raw) : null;
    const outcome: AiOutcome = asked.ok
      ? reply
        ? aiOutcome(p.ai, reply, {
            card,
            outline: plan.outline,
            input: cardInput,
            ...(choices.labels ? { labels: choices.labels } : {}),
          })
        : { failed: AI_UNREADABLE }
      : { failed: asked.reason };
    const done = await write(deps, input, card, outcome);
    const ok = done.ok;
    const text = done.text;
    settle(p, ok, text, { ai: true, ...(done.already ? { already: true } : {}) });
    if (!ok) deps.defer(reportServerEvent(env, 'Plan', 'Ran', 'AutomationAiFailed'));
    console.info('[automations] ai', {
      task,
      ok,
      tookMs: Date.now() - started,
      ...(ok ? {} : { reason: text }),
    });
  }
  return out;
}
